INSERT INTO `template` VALUES (2,'PO','<p>111111111</p>','N'),(3,'GRN','<p>55555</p>','N'),(4,'PO,GRN','<p>dgfsdfghdfh</p>','N'),(5,'GRN','<p>fsdfgd</p>','N'),(6,'GRN','<p>&lt;?php</p><p>class xtcpdf extends TCPDF {</p><p>}</p><p><br>&nbsp;</p><p>&nbsp; &nbsp;$this-&gt;set(\'pdf\', new TCPDF(\'P\',\'mm\',\'A4\'));</p><p>$pdf = new TCPDF(PDF_PAGE_ORIENTATION, PDF_UNIT, PDF_PAGE_FORMAT, true, \'UTF-8\', false, true);</p><p><br>&nbsp;</p><p>// set document information</p><p><br>&nbsp;</p><p>$pdf-&gt;SetCreator(PDF_CREATOR);</p><p>$pdf-&gt;SetPrintHeader(false);</p><p>$pdf-&gt;SetPrintFooter(false);</p><p>$pdf-&gt;AddPage();</p><p>//$pdf-&gt;setHeaderMargin(0);</p><p><br>&nbsp;</p><p>// set margins</p><p>//$//pdf-&gt;SetMargins(PDF_MARGIN_LEFT, PDF_MARGIN_TOP, PDF_MARGIN_RIGHT);</p><p>&nbsp;$pdf-&gt;SetAutoPageBreak(TRUE, 20);</p><p>//$pdf-&gt;SetMargins(0, 25, 0, true);</p><p><br>&nbsp;</p><p>$pdf-&gt;SetFont(\'\', \'\', 8, \'\', \'true\');</p><p>TCPDF_FONTS::addTTFfont(\'../Devanagari/Devanagari.ttf\', \'TrueTypeUnicode\', \"\", 32);</p><p><br><br>&nbsp;</p><p>$logo = WWW_ROOT . \"/images/\" . $site_details[\'small_logo\'];</p><p>$address &nbsp;= &nbsp;$site_details[\'address1\'];</p><p>$email &nbsp;= &nbsp;$site_details[\'email\'];</p><p>$mobile &nbsp;= &nbsp;$site_details[\'phone\'];</p><p>$website &nbsp;= &nbsp;$site_details[\'website\'];</p><p>$gst_no &nbsp;= &nbsp;$site_details[\'gst_no\'];</p><p>$pan_no &nbsp;= &nbsp;$site_details[\'pan_number\'];</p><p>$school_name &nbsp;= &nbsp;$sitesetting[\'first_name\'];</p><p><br>&nbsp;</p><p>$j=1;</p><p>$itemname = $this-&gt;comman-&gt;getitemname($indentpoid[\'finishedproduct_id\']);</p><p>$machineName = $this-&gt;comman-&gt;getMachineName($indentpoid[\'machine_id\']);</p><p>$contractname = $this-&gt;comman-&gt;findcontractname($indentpoid[\'contract_id\']);</p><p>if($indentpoid[\'updated\'] != \'\'){</p><p>&nbsp; &nbsp;$updatedate = date(\"d-m-Y\", strtotime($indentpoid[\'updated\']));</p><p>}</p><p><br>&nbsp;</p><p>$html .=\'</p><p>&lt;table border=\"1px\"&gt;</p><p>&nbsp; &lt;tr&gt;</p><p>&nbsp; &nbsp; &lt;td&gt;</p><p>&nbsp; &nbsp; &nbsp; &lt;table width=\"100%\" style=\"padding: 1px 1px 0px 0px;\" align=\"left\"&gt;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&lt;tbody&gt;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &lt;tr&gt;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&lt;td style=\"text-align:left\" width=\"50%\"&gt;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;img src=\"\'.$logo.\'\" alt=\"\" border=\"0\" style=\"display:block;\" height=\"62px;\"&gt;&lt;br&gt;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &lt;span style=\"display:block; color:#000; font-size:10px;\"&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;b&gt;\'.$school_name.\'&lt;/b&gt;&lt;/span&gt;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&lt;/td&gt;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&lt;td style=\"text-align:left;\" width=\"50%\" align=\"right\"&gt;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\'.$address.\'&lt;br&gt;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &lt;b&gt;Phone&lt;/b&gt;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; :\'.$mobile.\'&lt;br&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;b&gt;Email&lt;/b&gt;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; : &lt;u&gt;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; \'.$email.\'&lt;/u&gt;&lt;br&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;b&gt;Website&lt;/b&gt; :&amp;nbsp;\'.$website.\'</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&lt;/td&gt;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &lt;/tr&gt;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&lt;/tbody&gt;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &lt;/table&gt;</p><p>&nbsp; &nbsp; &nbsp; &lt;h3 style=\"text-align:center;font-size:10px; border-top:1px solid #000; border-bottom:1px solid #000;\"&gt;Indent Details&lt;/h3&gt;</p><p>&nbsp; &nbsp; &nbsp; &lt;table cellspacing=\"0\" cellpadding=\"3\" border=\"0px\" style=\"font-size:8px;\"&gt;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &lt;thead&gt;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &lt;tr&gt;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &lt;td&gt;&lt;b&gt;Indent Id :-&lt;/b&gt;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\'. $indentpoid[\'indent_id\'] .\'</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &lt;/td&gt;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &lt;td&gt;&lt;b&gt;Contract name :-&lt;/b&gt;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; \'. &nbsp;$contractname[\'title\'] . \'(\' . $contractname[\'workorder\'] . \')</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &lt;/td&gt;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &lt;/tr&gt;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &lt;tr&gt;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &lt;td&gt;&lt;b&gt;Product :-&lt;/b&gt;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\'. &nbsp;$itemname[\'item_name\'].\'</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &lt;/td&gt;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &lt;td&gt;&lt;b&gt;Machine Name :-&lt;/b&gt;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; \'. &nbsp;$machineName[\'machine_name\'].\'</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&lt;/td&gt;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &lt;/tr&gt;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &lt;tr&gt;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &lt;td&gt;&lt;b&gt;Issue By :-&lt;/b&gt;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; \'. $indentpoid[\'issued_name\'] .\'</p><p>&nbsp; &nbsp; &nbsp; &nbsp;&lt;/td&gt;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &lt;td&gt;&lt;b&gt;Issue Date :-&lt;/b&gt;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\'. date(\"d-m-Y\", strtotime($indentpoid[\'issue_date\'])) .\'</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &lt;/td&gt;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &lt;/tr&gt;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &lt;tr&gt;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &lt;td&gt;&lt;b&gt;Last Updated Date :-&lt;/b&gt;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\'. $updatedate .\'</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &lt;/td&gt;</p><p>&nbsp; &nbsp; &nbsp; &lt;/tr&gt;</p><p>&nbsp; &nbsp; &nbsp;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &lt;/thead&gt;</p><p>&nbsp; &nbsp; &nbsp;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &lt;/table&gt;</p><p>&nbsp; &nbsp; &lt;/td&gt;</p><p>&nbsp; &lt;/tr&gt;</p><p>&lt;/table&gt;\';</p><p>&nbsp;</p><p><br>&nbsp;</p><p>&nbsp; $html .=\'</p><p>&lt;h6 style=\"text-align:center;font-size:10px;\"&gt;Raw Material&lt;/h6&gt;</p><p>&lt;table cellspacing=\"0\" cellpadding=\"3\" border=\"1px\" style=\"font-size:8px;\"&gt;</p><p>&lt;thead&gt;</p><p>&lt;tr&gt;</p><p>&lt;th width=\"08%\" &gt;&lt;strong&gt;S.No.&lt;/strong&gt;&lt;/th&gt;</p><p>&lt;th width=\"62%\" &gt;&lt;strong&gt;Item&lt;/strong&gt;&lt;/th&gt;</p><p>&lt;th width=\"20%\" &gt;&lt;strong&gt;Issue Qty&lt;/strong&gt;&lt;/th&gt;</p><p>&lt;th width=\"10%\" &gt;&lt;strong&gt;UOM&lt;/strong&gt;&lt;/th&gt;</p><p>&lt;/tr&gt;</p><p>&lt;/thead&gt;</p><p><br>&nbsp;</p><p>&nbsp; &nbsp; &lt;tbody&gt;\';</p><p>&nbsp; &nbsp; foreach ($indentpodetails as $value) {</p><p>&nbsp; &nbsp; &nbsp; $itemname1 = $this-&gt;comman-&gt;getitemcatcom($value[\'item_id\']);</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; if (!empty($itemname1[\'measurementunit\'][\'unit_name\'])) {</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; $unitname = $itemname1[\'measurementunit\'][\'unit_name\'];</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; } else {</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; $unitname = \"-\";</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; };</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; $html .=\'</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &lt;tr&gt;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &lt;th width=\"08%\" &gt;\'.$j.\'.&lt;/th&gt;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &lt;td width=\"62%\" &gt;\'.ucfirst($itemname1[\'item_name\']).\'&lt;/td&gt;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &lt;td width=\"20%\" style =\"text-align:right;\"&gt;\'.sprintf(\'%.2f\',$value[\'quantity\']).\'&lt;/td&gt;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &lt;td width=\"10%\" &gt;\'.$unitname.\'&lt;/td&gt;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &lt;/tr&gt;\';</p><p>&nbsp; &nbsp; &nbsp; $j++;</p><p>&nbsp; &nbsp; }</p><p>&nbsp; &nbsp; $html .=\'</p><p>&nbsp; &nbsp; &nbsp; &lt;/table&gt;</p><p>&lt;br&gt;</p><p>&lt;br&gt;</p><p>&lt;br&gt;</p><p>&lt;br&gt;</p><p><br><br>&nbsp;</p><p>&nbsp; &nbsp; &nbsp; &lt;table cellspacing=\"0\" cellpadding=\"3\" border=\"0px\" style=\"font-size:8px;\"&gt;</p><p>&nbsp; &lt;thead&gt;</p><p>&nbsp; &lt;tr&gt;</p><p>&nbsp; &lt;th width=\"33%\" &gt;&lt;strong&gt;INDENTER&lt;/strong&gt;&lt;/th&gt;</p><p>&nbsp; &lt;td width=\"33%\" style =\"text-align:center;\"&gt;&lt;strong&gt;ISSUED BY&lt;/strong&gt;&lt;/td&gt;</p><p>&nbsp; &lt;td width=\"34%\" style =\"text-align:right;\"&gt;&lt;strong&gt;RECEIVED BY&lt;/strong&gt;&lt;/td&gt;</p><p>&nbsp; &lt;/tr&gt;</p><p>&nbsp; &nbsp; &lt;/thead&gt;</p><p>&nbsp; &nbsp; &nbsp; &lt;/table&gt;</p><p><br>&nbsp;</p><p>&nbsp; &nbsp; &nbsp; \';</p><p><br><br><br>&nbsp;</p><p>// echo $html;die;</p><p><br>&nbsp;</p><p>$date = date(\'d-m-y\');</p><p>$pdf-&gt;writeHTMLCell(0, 0, \'\', \'\', utf8_encode($html), 0, 1, 0, true, \'\', true);</p><p>//$pdf-&gt;WriteHTML($html, true, false, true, false, \'\');</p><p>ob_end_clean();</p><p>echo $pdf-&gt;Output(\'Indent_Details_\'.$indentpoid[\'indent_id\'].\'_\'.$date.\'.pdf\');</p><p>exit;</p><p>?&gt;</p><p>&nbsp;</p>','Y'),(7,'GRN','<p>15151</p>','N'),(8,'PO','<p>&lt;?php<br>// Start output buffering<br>ob_start();</p><p>// Creating PDF<br>$pdf = new TCPDF(\'P\', \'mm\', \'A4\');<br>$pdf-&gt;SetCreator(PDF_CREATOR);<br>$pdf-&gt;SetPrintHeader(false);<br>$pdf-&gt;SetPrintFooter(true);<br>$pdf-&gt;SetDefaultMonospacedFont(PDF_FONT_MONOSPACED);<br>$pdf-&gt;AddPage();<br>$pdf-&gt;SetFont(\'\', \'\', 10, \'\', \'false\');<br>$pdf-&gt;SetMargins(10, 10, 10, 0);</p><p>// Prepare basic HTML content for debugging<br>$html = \'&lt;html&gt;&lt;body&gt;&lt;h1&gt;Hello, PDF!&lt;/h1&gt;&lt;/body&gt;&lt;/html&gt;\'; // Test with basic HTML</p><p>// Writing HTML content to PDF<br>$pdf-&gt;writeHTML($html, true, false, true, false, \'\');</p><p>// Clean the buffer to avoid sending any unwanted output before PDF<br>ob_end_clean();</p><p>// Final Output<br>$pdf-&gt;Output(\'test.pdf\', \'I\');<br>exit;<br>?&gt;<br>&nbsp;</p>','Y'),(9,'Operify  Demo Request','<!DOCTYPE HTML>\n 			<html>\n 			<head>\n 			<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\">\n 			<title>Mail</title>\n 			</head>\n 			<body style=\"margin:0px; padding:0px; font-family:Arial, Helvetica, sans-serif;background:#fff;\"><div style=\"margin:auto;text-align:center;width:620px;border:5px solid #86a9e3;\">\n \n 			<div style=\" padding:10px;\">  <div style=\"text-align:center;\"> <img src=\"https://staging.operify.in/image/logo.png\" /><br>\n \n 			</div>\n 				<div style=\"text-align:left;\">\n 					<h5 style=\"color: #86a9e3;font-size: 14px;padding: 0 0px; display:inline-block; margin-bottom:0; width:auto; font-family:Arial, Helvetica, sans-serif; \">Hi <strong style=\"color:#86a9e3;\">Admin</strong>,</h5>\n \n \n 			<hr style=\"border:1px solid #eee\">\n 					<h3 style=\"font-size:14px;color:#000;\">Demo request detail are :-</h3>\n 					<p><span style=\"width: 190px; display:inline-block; font-size:14px;\">Name: </span><span style=\"color:#86a9e3; font-size:14px;\">{name}</span></p>\n \n 					<p><span style=\"width: 190px; display:inline-block; font-size:14px;\">Title: </span><span style=\"color:#86a9e3; font-size:14px;\">{title}</span></p>\n 				\n					 <p><span style=\"width: 190px; display:inline-block; font-size:14px;\">Email: </span><span style=\"color:#86a9e3; font-size:14px;\">{email}</span></p>\n\n 					<p><span style=\"width: 190px; display:inline-block; font-size:14px;\">Phone: </span><span style=\"color:#86a9e3; font-size:14px;\">{phone}</span></p>\n\n 					<p><span style=\"width: 190px; display:inline-block; font-size:14px;\">Day: </span><span style=\"color:#86a9e3; font-size:14px;\">{day}</span></p>\n\n 					<p><span style=\"width: 190px; display:inline-block; font-size:14px;\">Time: </span><span style=\"color:#86a9e3; font-size:14px;\">{time}</span></p>\n\n 					<p><span style=\"width: 190px; display:inline-block; font-size:14px;\">Message: </span><span style=\"color:#86a9e3; font-size:14px;\">{comments}</span></p>\n \n 				<hr style=\"border:1px solid #eee\">\n 				<p>Thank you for contacting us, we look forward to replying to your inquiry!&nbsp;</p>\n \n 			<p>All Our Love... Team </p>\n 			</hr>\n 				</div>\n 				</div>  <div style=\"color:#fff; background:#86a9e3; padding:5px;font-size: 14px;\"> Operify&reg;&nbsp; |&nbsp; <a href=\"http://www.operify.in/\">operify.com</a> &nbsp;|&nbsp; Copyright {year}. All Rights Reserved.</div>\n 			</div>\n 			</body></html>','Y');
/*!40000 ALTER TABLE `template` ENABLE KEYS */;
