--
-- Table structure for table `vendors`
--

DROP TABLE IF EXISTS `vendors`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `vendors` (
  `id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL,
  `address` text CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci,
  `state_id` int DEFAULT NULL,
  `contact_no` varchar(200) DEFAULT NULL,
  `email` text,
  `vat_no` varchar(255) DEFAULT NULL,
  `tin_no` varchar(255) DEFAULT NULL,
  `tin_date` date DEFAULT NULL,
  `gst_number` varchar(255) DEFAULT NULL,
  `pancard_number` varchar(15) DEFAULT NULL COMMENT '\n',
  `tds` enum('0','1') NOT NULL DEFAULT '0',
  `description` text,
  `created_date` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `status` enum('Y','N') NOT NULL,
  `contact_person` varchar(255) DEFAULT NULL,
  `type` enum('Vendor','Transporter','Customer') DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `name` (`name`),
  KEY `id` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=219 DEFAULT CHARSET=latin1;
/*!40101 SET character_set_client = @saved_cs_client */;

